 "new_string": "def transform(grid):
    # Hollow rectangular outlines encode a filling based on their interior area:
    # the 1-cell interior case becomes 7, while larger interiors become 2.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r0 in range(h):
        for c0 in range(w):
            color = grid[r0][c0]
            if color == 9:
                continue
            # rectangles are recognized from contiguous same-color top/left edges
            for r1 in range(r0+2, h):
                for c1 in range(c0+2, w):
                    if grid[r1][c0] != color or grid[r0][c1] != color or grid[r1][c1] != color:
                        continue
                    if any(grid[r0][c] != color or grid[r1][c] != color for c in range(c0,c1+1)):
                        continue
                    if any(grid[r][c0] != color or grid[r][c1] != color for r in range(r0,r1+1)):
                        continue
                    interior = [grid[r][c] for r in range(r0+1,r1) for c in range(c0+1,c1)]
                    if not interior or any(v != 9 for v in interior):
                        continue
                    fill = 7 if len(interior) == 1 else 2
                    for r in range(r0+1,r1):
                        for c in range(c0+1,c1):
                            out[r][c] = fill
    return out
