def transform(grid):
    """Fill square hollow frames according to their side-length parity."""
    h = len(grid)
    w = max(map(len, grid))
    widths = [len(row) for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    base = [row + [background] * (w - len(row)) for row in grid]
    out = [row[:] for row in base]

    for r0 in range(h):
        for c0 in range(w):
            color = base[r0][c0]
            if color == background:
                continue
            for side in range(3, min(h - r0, w - c0) + 1):
                r1, c1 = r0 + side - 1, c0 + side - 1
                if any(c1 >= widths[r] for r in range(r0, r1 + 1)):
                    continue
                if not all(base[r0][c] == color and base[r1][c] == color
                           for c in range(c0, c1 + 1)):
                    continue
                if not all(base[r][c0] == color and base[r][c1] == color
                           for r in range(r0, r1 + 1)):
                    continue
                if not all(base[r][c] == background
                           for r in range(r0 + 1, r1)
                           for c in range(c0 + 1, c1)):
                    continue
                fill = 7 if side % 2 else 2
                for r in range(r0 + 1, r1):
                    for c in range(c0 + 1, c1):
                        out[r][c] = fill
    return [row[:widths[i]] for i, row in enumerate(out)]
